const $=id=>document.getElementById(id);let modules=[],state={drafts:{},passed:{},revealed:{},current:0},worker,timer;const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const saved=JSON.parse(localStorage.getItem('ts-lab-v1'));if(saved&&saved.drafts&&saved.passed&&saved.revealed)state=saved;}catch{}
function save(){try{localStorage.setItem('ts-lab-v1',JSON.stringify(state));$('save').textContent='Draft saved';}catch{$('save').textContent='Not saved';$('storage').textContent='Browser storage unavailable. Export your progress to keep it.';}}
function navigation(){const n=Object.values(state.passed).filter(Boolean).length;$('overall').textContent=`${n} of ${modules.length} modules completed`;$('progress').value=n;$('modules').innerHTML=modules.map((m,i)=>`<button data-i="${i}" class="${state.current===i?'active':''}" ${state.current===i?'aria-current="step"':''}><span class="number">${state.passed[i]?'✓':String(i+1).padStart(2,'0')}</span>${escape(m.title)}</button>`).join('');$('modules').querySelectorAll('button').forEach(b=>b.onclick=()=>select(Number(b.dataset.i)));}
function select(i){if(!Number.isInteger(i)||i<0||i>=modules.length)throw Error('Invalid module');stop();state.current=i;save();const m=modules[i];$('eyebrow').textContent=`MODULE ${String(i+1).padStart(2,'0')} / ${m.level.toUpperCase()}`;$('title').textContent=m.title;$('meta').textContent='Read the lesson, solve the challenge, and pass every check.';$('lesson').textContent=m.lesson;$('example').textContent=m.example;$('task').textContent=m.task;$('criteria').innerHTML=m.tests.map(t=>`<li>${escape(t[0])}</li>`).join('');$('hint').textContent=m.hint;$('solution').textContent=m.solution;$('solutionBox').open=false;$('code').value=state.drafts[i]??m.starter;$('status').textContent=state.passed[i]?'Completed':'In progress';$('feedback').textContent=state.passed[i]?'Previously passed. Edit and rerun to practice again.':'Write your implementation, then run the assessment. All checks must pass to complete this module.';$('previous').disabled=i===0;$('next').disabled=i===modules.length-1;$('footerNote').textContent=Object.values(state.passed).filter(Boolean).length===modules.length?'All modules passed. Rebuild the final exercise independently next.':'Learn → implement → test → repeat';navigation();}
function stop(){if(worker)worker.terminate();worker=null;clearTimeout(timer);$('run').disabled=false;$('run').textContent='Run assessment';}
function run(){stop();const index=state.current;const code=$('code').value;state.drafts[index]=code;save();$('run').disabled=true;$('run').textContent='Checking…';$('feedback').textContent='Running strict type checks and behavioral tests…';worker=new Worker('runner.js');worker.onmessage=({data:r})=>{stop();if(r.error){$('feedback').textContent=r.error;return;}const total=r.results.length;const passed=r.results.filter(x=>x.ok).length;const complete=!r.diagnostics.length&&passed===total;state.passed[index]=complete;save();navigation();$('status').textContent=complete?'Completed':'Keep practicing';$('feedback').innerHTML=(complete?`<div class="success">All checks passed. ${state.revealed[index]?'Solution viewed — try a fresh independent attempt next.':'Ready for the next module.'}</div>`:`<strong>${passed}/${total} behavioral checks passed</strong>`)+r.diagnostics.map(d=>`<div class="diagnostic">${escape(d)}</div>`).join('')+r.results.map(t=>`<div class="result ${t.ok?'pass':'fail'}">${t.ok?'✓':'×'} ${escape(t.name)}${t.error?`<br>${escape(t.error)}`:''}</div>`).join('');};worker.onerror=()=>{stop();$('feedback').textContent='The assessment runner could not start. Reload and try again.';};timer=setTimeout(()=>{stop();$('feedback').textContent='Execution exceeded 6 seconds. Check for infinite loops or unresolved promises.';},6000);worker.postMessage({code,module:modules[index]});}
$('code').oninput=()=>{state.drafts[state.current]=$('code').value;state.passed[state.current]=false;$('status').textContent='Draft changed';save();navigation();};$('code').onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}if(e.key==='Tab'){e.preventDefault();const el=e.target;el.setRangeText('  ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input'));}};$('run').onclick=run;$('reset').onclick=()=>{if(confirm('Replace your code with the starter?')){state.drafts[state.current]=modules[state.current].starter;state.passed[state.current]=false;select(state.current);}};$('retry').onclick=()=>{state.drafts[state.current]=modules[state.current].starter;state.passed[state.current]=false;select(state.current);};$('solutionBox').ontoggle=()=>{if($('solutionBox').open){state.revealed[state.current]=true;save();}};$('previous').onclick=()=>select(state.current-1);$('next').onclick=()=>select(state.current+1);
$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}));a.download='typescript-lab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('File too large');const s=JSON.parse(await file.text());if(s.version!==1||!Number.isInteger(s.current)||s.current<0||s.current>=modules.length||!s.drafts||!s.passed||!s.revealed)throw Error('Invalid format');for(const [k,v] of Object.entries(s.drafts))if(!/^\d+$/.test(k)||+k>=modules.length||typeof v!=='string')throw Error('Invalid draft');for(const obj of [s.passed,s.revealed])for(const [k,v] of Object.entries(obj))if(!/^\d+$/.test(k)||+k>=modules.length||typeof v!=='boolean')throw Error('Invalid progress');if(confirm('Replace this browser’s progress with the imported file?')){state={current:s.current,drafts:s.drafts,passed:s.passed,revealed:s.revealed};select(state.current);$('storage').textContent='Progress imported.';}}catch{$('storage').textContent='Could not import. Choose a valid TypeScript Lab export.';}e.target.value='';};
fetch('modules.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{modules=data;select(Number.isInteger(state.current)&&state.current<modules.length?state.current:0);try{document.modelContext?.registerTool({name:'open_learning_module',description:'Open a TypeScript learning module by its zero-based index.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0,maximum:10}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({index})=>{select(index);return {index,title:modules[index].title};}});}catch{}}).catch(()=>{$('title').textContent='Could not load lessons';$('feedback').textContent='Reload to try again.';});
